-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Physical Sciences — Computer Science
-- Course outlines transcribed from the department's own current course
-- outline (computersci.unn.edu.ng/course-modules/ -> "4-Year Standard
-- Undergraduate Degree Programme in B.Sc", downloaded 2026-08-08), which
-- includes full course descriptions for every COS major and elective course.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for these courses are removed first, so it updates rather than duplicates.
--
-- This file also carries the required ancillary, general-studies and elective
-- courses a Computer Science student actually sits each semester (MTH, PHY,
-- GSP, CHM, BIO, STA, CED), scoped to department = 'Computer Science' so they
-- appear on a Computer Science student's own timetable — independent rows
-- from any same-code row filed under its own home department. Ancillary
-- descriptions are reused, unedited, from this app's Mathematics/Physics
-- outlines where the code, level, semester and subject genuinely match;
-- GSP/CED carry code/title/units/level/semester only, since no verified
-- description exists anywhere yet.
--
-- Two source discrepancies, both left as printed with the affected course
-- flagged rather than silently corrected:
-- * The elective "Computer System Performance Evaluation" appears as
--   "COS 413" in the programme's own course table, but its own description
--   heading is "COS 416" — a code that appears nowhere in the table. The
--   table's code (COS 413) is used, carrying the COS 416 description.
-- * Several courses' unit counts differ between the programme table and
--   their own description heading (e.g. COS 337, COS 472, COS 414, COS 436,
--   COS 478, COS 337). The description heading's count is used throughout,
--   as the more detailed and specific of the two sources.
--
-- The source document does not cover Third Year, Second Semester beyond the
-- SIWES block, nor does it show a Third Year "Second Semester" set of
-- ancillary/GSP courses — students appear to take only SIWES that semester.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Computer Science';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('COS 101', 'Introduction to Computer Science', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Concepts of hardware and software; basic subsystems of a digital computer; characteristics of a digital computer; devices/media; types/classes of computer emphasising the PC; history of computers and their generations. Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program. Programming: introduction to Java/BASIC programming language syntax and programming. Booting and shutdown; types of operating system; user interface; managing information, computer malware (virus, etc); computer network; internet and web usage, e-mail, instant messaging, etc. Office applications; use of a statistical package and a database management system.', '["Concepts of hardware and software","basic subsystems of a digital computer","characteristics of a digital computer","devices/media","types/classes of computer emphasising the PC","history of computers and their generations","Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program","Programming: introduction to Java/BASIC programming language syntax and programming","Booting and shutdown","types of operating system","user interface","managing information, computer malware (virus, etc)","computer network","internet and web usage, e-mail, instant messaging, etc","Office applications","use of a statistical package and a database management system"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 141', 'Computer Hardware', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Overview of concepts and key terminologies; electrostatic discharge (ESD), cases and form factor, power supply; connectors, voltage, motherboard and components, chipsets and form factors, CPU, cooling system, computer circuits, diode array, PIAs, etc; integrated circuits fabrication process. Use of small, medium, large and very large scale integrated circuits, hardware design. Memories: primary and secondary memories, core memory, etc; magnetic devices — disks, tapes, video disks, etc; peripheral devices, printers, CRTs, keyboards, character recognition. Operational amplifiers, analog-to-digital and digital-to-analog converters.', '["Overview of concepts and key terminologies","electrostatic discharge (ESD), cases and form factor, power supply","connectors, voltage, motherboard and components, chipsets and form factors, CPU, cooling system, computer circuits, diode array, PIAs, etc","integrated circuits fabrication process","Use of small, medium, large and very large scale integrated circuits, hardware design","Memories: primary and secondary memories, core memory, etc","magnetic devices — disks, tapes, video disks, etc","peripheral devices, printers, CRTs, keyboards, character recognition","Operational amplifiers, analog-to-digital and digital-to-analog converters"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 102', 'Introduction to Problem Solving', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 3, 'Problem solving strategies; concepts and properties of algorithm; role of algorithm in the problem solving process; characteristics of a good algorithm; steps involved in algorithm development. Problem solving strategies: top-down and bottom-up methods; implementation strategies; developing an algorithm for a simple problem; representation of algorithms — flowcharts and pseudocodes; development of flowcharts and pseudocodes, flowchart symbols and uses, program objects. Implementation of algorithms in a programming language such as Visual Basic, Java, C, or C++.', '["Problem solving strategies","concepts and properties of algorithm","role of algorithm in the problem solving process","characteristics of a good algorithm","steps involved in algorithm development","Problem solving strategies: top-down and bottom-up methods","implementation strategies","developing an algorithm for a simple problem","representation of algorithms — flowcharts and pseudocodes","development of flowcharts and pseudocodes, flowchart symbols and uses, program objects","Implementation of algorithms in a programming language such as Visual Basic, Java, C, or C++"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 124', 'Introduction to Database System', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 3, 'Information storage and retrieval, information management applications, information capture and representation, analysis and indexing, search, retrieval, information privacy, integrity, security, scalability, efficiency and effectiveness. Introduction to database systems: components of database systems, DBMS functions, database architecture and data independence, database design and creation using a database management system. Functions of a database; uses in business and industry. Introduction to data dictionaries, normalisation, data integrity, data modelling, creation of simple tables, editing a database, queries, reports and forms using SQL.', '["Information storage and retrieval, information management applications, information capture and representation, analysis and indexing, search, retrieval, information privacy, integrity, security, scalability, efficiency and effectiveness","Introduction to database systems: components of database systems, DBMS functions, database architecture and data independence, database design and creation using a database management system","Functions of a database","uses in business and industry","Introduction to data dictionaries, normalisation, data integrity, data modelling, creation of simple tables, editing a database, queries, reports and forms using SQL"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 261', 'Computer Programming I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Introduction to problem solving methods and algorithm development; designing, coding, debugging and documenting programs using techniques of good programming style. An IDE; the Java virtual machine; writing a Java program, packages, simple Java programs; data types; control constructs; classes; keyboard input; file I/O using byte streams, character streams, and buffered streams; writing text files in Java; the File class; standard streams.', '["Introduction to problem solving methods and algorithm development","designing, coding, debugging and documenting programs using techniques of good programming style","An IDE","the Java virtual machine","writing a Java program, packages, simple Java programs","data types","control constructs","classes","keyboard input","file I/O using byte streams, character streams, and buffered streams","writing text files in Java","the File class","standard streams"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 265', 'Foundations of Sequential Program', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Introduction to high level language computers: meaning, justifications, arguments for and against high level language computers, high level language computer systems and architecture. The relationship between high level languages and the computer architecture that underlies their implementation; basic machine architecture, specification and translation of programming language blocks; structured languages, parameter passing mechanisms.', '["Introduction to high level language computers: meaning, justifications, arguments for and against high level language computers, high level language computer systems and architecture","The relationship between high level languages and the computer architecture that underlies their implementation","basic machine architecture, specification and translation of programming language blocks","structured languages, parameter passing mechanisms"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 235', 'Compiler Construction I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Review of compilers, assemblers and interpreters; structure and functional aspects of a typical compiler; syntax, semantics and pragmatics; functional relationship between lexical analysis, expression analysis and code generation. Internal form of the course programme. Use of a standard compiler as a working vehicle. Error detection and recovery; grammar and languages — the parsing problem; the scanner.', '["Review of compilers, assemblers and interpreters","structure and functional aspects of a typical compiler","syntax, semantics and pragmatics","functional relationship between lexical analysis, expression analysis and code generation","Internal form of the course programme","Use of a standard compiler as a working vehicle","Error detection and recovery","grammar and languages — the parsing problem","the scanner"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 271', 'Data Communication and Networking', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Introduction: data and information, data processing systems, data communication systems, signals. Introduction to analogue and digital time and frequency domain concepts, Fourier transform, A/D conversions, Fourier series, measures of communication channel characteristics, Nyquist and Shannon information capacity, transmission media, noise and distortion, modulation and demodulation, multiplexing and demultiplexing, synchronous and asynchronous data transmission, error detection and control techniques. Bus structures and loop systems, computer networks, examples and design considerations, data switching principles, broadcast techniques, network structure for packet switching, protocol description of networks, e.g. ARPANET.', '["Introduction: data and information, data processing systems, data communication systems, signals","Introduction to analogue and digital time and frequency domain concepts, Fourier transform, A/D conversions, Fourier series, measures of communication channel characteristics, Nyquist and Shannon information capacity, transmission media, noise and distortion, modulation and demodulation, multiplexing and demultiplexing, synchronous and asynchronous data transmission, error detection and control techniques","Bus structures and loop systems, computer networks, examples and design considerations, data switching principles, broadcast techniques, network structure for packet switching, protocol description of networks, e.g","ARPANET"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 243', 'Computer Architecture and Organization I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Fundamental building blocks, logic expression, minimisation, sum of product forms, register transfer notation, physical considerations, data representation and number bases, fixed and floating point systems, representation, memory system organisation and architecture.', '["Fundamental building blocks, logic expression, minimisation, sum of product forms, register transfer notation, physical considerations, data representation and number bases, fixed and floating point systems, representation, memory system organisation and architecture"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 236', 'Software Engineering I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Basic concepts of software engineering; software development process — problem analysis, requirement gathering, design, implementation, testing and maintenance, choice of programming language; Object Oriented Analysis and Design (OOAD); implementation of model/non-model based engineering processes.', '["Basic concepts of software engineering","software development process — problem analysis, requirement gathering, design, implementation, testing and maintenance, choice of programming language","Object Oriented Analysis and Design (OOAD)","implementation of model/non-model based engineering processes"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 264', 'Computer Programming II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Principles of good programming, structured programming concepts, structured program constructs, advantages of writing structured programs, unstructured programming constructs (e.g. the GOTO statement) and their disadvantages, data structures, debugging and testing, string processing, internal searching and sorting, recursion. Uses a programming language different from COS 261, e.g. C.', '["Principles of good programming, structured programming concepts, structured program constructs, advantages of writing structured programs, unstructured programming constructs (e.g. the GOTO statement) and their disadvantages, data structures, debugging and testing, string processing, internal searching and sorting, recursion","Uses a programming language different from COS 261, e.g"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 232', 'Data Structures', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Primitive data types; data structures — array, record, strings, list; string processing; data representation in memory — static and heap allocation; runtime storage management, pointers and references; implementation strategies for stack, queue, hash table, graph and tree; choosing the right data structure; high-level language data types and data-handling facilities.', '["Primitive data types","data structures — array, record, strings, list","string processing","data representation in memory — static and heap allocation","runtime storage management, pointers and references","implementation strategies for stack, queue, hash table, graph and tree","choosing the right data structure","high-level language data types and data-handling facilities"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 234', 'Operating System I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Overview of operating systems, examples, objectives and role, history, operating system structure, system components, operating system services, system calls and system programs. Process management, CPU scheduling, scheduling algorithms, memory management. Mechanisms supporting client-server models and hand-held devices; design issues; influences of security, networking and multimedia. Operating system principles: structuring methods, abstraction of resources, concepts of APIs, device organisation, interrupts.', '["Overview of operating systems, examples, objectives and role, history, operating system structure, system components, operating system services, system calls and system programs","Process management, CPU scheduling, scheduling algorithms, memory management","Mechanisms supporting client-server models and hand-held devices","design issues","influences of security, networking and multimedia","Operating system principles: structuring methods, abstraction of resources, concepts of APIs, device organisation, interrupts"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 361', 'Object Oriented Programming', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Basic OOP concepts: classes, objects, inheritance, polymorphism, data abstraction. Tools for developing, compiling, interpreting and debugging Java programs; Java syntax and data objects, operators; control flow constructs; objects and classes programming; arrays; methods; exceptions; applets and the Abstract Windows Toolkit; persistence. Laboratory exercises in an OOP language.', '["Basic OOP concepts: classes, objects, inheritance, polymorphism, data abstraction","Tools for developing, compiling, interpreting and debugging Java programs","Java syntax and data objects, operators","control flow constructs","objects and classes programming","arrays","methods","exceptions","applets and the Abstract Windows Toolkit","persistence","Laboratory exercises in an OOP language"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 311', 'Switching Algebra & Discrete Structures', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Basic set theory: definitions, relations, equivalence relation, partition, ordered sets. Boolean algebra and lattices, logic. Graph theory: directed and undirected graphs, graph isomorphism, basic graph theorems. Matrices: integer and real matrices, Boolean matrices, path matrices, adjacency vectors/matrices — path adjacency matrix, numerical and Boolean adjacency matrices. Applications to counting, discrete probability generating functions.', '["Basic set theory: definitions, relations, equivalence relation, partition, ordered sets","Boolean algebra and lattices, logic","Graph theory: directed and undirected graphs, graph isomorphism, basic graph theorems","Matrices: integer and real matrices, Boolean matrices, path matrices, adjacency vectors/matrices — path adjacency matrix, numerical and Boolean adjacency matrices","Applications to counting, discrete probability generating functions"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 331', 'Operating Systems II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Concurrency: states and state diagrams, structures, dispatching and context switching, interrupts, concurrent execution, the mutual exclusion problem and some solutions. Deadlock: models and mechanisms (semaphores, monitors, etc); producer-consumer problem and synchronisation; multiprocessor issues; scheduling and dispatching. Memory management: overlays, swapping and partition, paging and segmentation, placement and replacement policies, working sets and thrashing, caching.', '["Concurrency: states and state diagrams, structures, dispatching and context switching, interrupts, concurrent execution, the mutual exclusion problem and some solutions","Deadlock: models and mechanisms (semaphores, monitors, etc)","producer-consumer problem and synchronisation","multiprocessor issues","scheduling and dispatching","Memory management: overlays, swapping and partition, paging and segmentation, placement and replacement policies, working sets and thrashing, caching"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 333', 'Software Engineering II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Software tools and environment: requirement analysis and design modelling tools — systems model, process models, DFDs, state transition, state charts, data models, ER modelling, object-oriented modelling using UML, software verification and validation, software testing, tool integration mechanisms, software quality assurance. Programming environments, testing tools. Software design: software architecture, design patterns, O.O. analysis and design, design for reuse. Using APIs: API programming, browsers and related tools, component-based computing.', '["Software tools and environment: requirement analysis and design modelling tools — systems model, process models, DFDs, state transition, state charts, data models, ER modelling, object-oriented modelling using UML, software verification and validation, software testing, tool integration mechanisms, software quality assurance","Programming environments, testing tools","Software design: software architecture, design patterns, O.O. analysis and design, design for reuse","Using APIs: API programming, browsers and related tools, component-based computing"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 335', 'Artificial Intelligence I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Introduction to artificial intelligence. Problem formulation and search: heuristic search, production systems. Knowledge representation: semantic networks and frames, propositional logic, first order predicate logic, fuzzy logic. Other methods for reasoning. Introduction to pattern recognition; multilayer neural networks; self-organising neural networks.', '["Introduction to artificial intelligence","Problem formulation and search: heuristic search, production systems","Knowledge representation: semantic networks and frames, propositional logic, first order predicate logic, fuzzy logic","Other methods for reasoning","Introduction to pattern recognition","multilayer neural networks","self-organising neural networks"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 341', 'Computer Architecture and Organization II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Memory system, general characteristics of memory operation (technology: magnetic recording, semi-conductor memory, coupled devices, magnetic bubbles). Memory addressing, memory hierarchy, virtual memory control systems. Hardware control, micro-programmed control, asynchronous control, I/O control. Introduction to the methodology of fault-tolerant computing.', '["Memory system, general characteristics of memory operation (technology: magnetic recording, semi-conductor memory, coupled devices, magnetic bubbles)","Memory addressing, memory hierarchy, virtual memory control systems","Hardware control, micro-programmed control, asynchronous control, I/O control","Introduction to the methodology of fault-tolerant computing"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 337', 'System Analysis and Design', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Overview of system analysis and design, business system concepts, system characteristics and elements, types of systems, systems models, categories of information, planning and control for system success, project selection, sources of project requests. Determining the user''s information requirements and strategies; information gathering; prototyping. Managing project review and selection, preliminary investigation, conducting the investigation, testing project feasibility. System requirement specifications: requirements determination, fact-finding techniques — interview, questionnaire, record review and observation. System development life cycle: purpose and key elements, process models — waterfall, iterative, agile (Scrum). Structured analysis: data flow diagrams, data dictionary, decision trees, identifying data requirements, decision tables. Data modelling: entity relationship model, decision tree and table, Unified Modelling Language — use case, sequence and activity diagrams. System design: structure charts, form designs, database design, security, automated tools for design.', '["Overview of system analysis and design, business system concepts, system characteristics and elements, types of systems, systems models, categories of information, planning and control for system success, project selection, sources of project requests","Determining the user''s information requirements and strategies","information gathering","prototyping","Managing project review and selection, preliminary investigation, conducting the investigation, testing project feasibility","System requirement specifications: requirements determination, fact-finding techniques — interview, questionnaire, record review and observation","System development life cycle: purpose and key elements, process models — waterfall, iterative, agile (Scrum)","Structured analysis: data flow diagrams, data dictionary, decision trees, identifying data requirements, decision tables","Data modelling: entity relationship model, decision tree and table, Unified Modelling Language — use case, sequence and activity diagrams","System design: structure charts, form designs, database design, security, automated tools for design"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 382', 'Students Industrial Work Experience Scheme', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'second', 6, 'Students spend six months on industrial attachment, taken from the second semester of the third year, for industrial training. A comprehensive log-book, certified by the industrial supervisor, shows that the student actually participated in the SIWES.', '["Students spend six months on industrial attachment, taken from the second semester of the third year, for industrial training","A comprehensive log-book, certified by the industrial supervisor, shows that the student actually participated in the SIWES"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 384', 'Technical SIWES Report', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'second', 5, 'At the end of the six consecutive months of industrial training, the student is expected to submit a technical report to the Department.', '["At the end of the six consecutive months of industrial training, the student is expected to submit a technical report to the Department"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 386', 'SIWES Seminar', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'second', 4, 'At the end of the six consecutive months of industrial training, each student is expected to present a seminar on the industrial training experience, emphasising latest developments in Computer Science in relation to their industrial experience.', '["At the end of the six consecutive months of industrial training, each student is expected to present a seminar on the industrial training experience, emphasising latest developments in Computer Science in relation to their industrial experience"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 411', 'Computational Science and Numerical Methods', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Operations research: game theory, network models, inventory models. Numerical computation: techniques for the computer implementation of algorithms for interpolation, approximation, numerical integration, etc. Graphical computation, modelling and simulation, high performance computation.', '["Operations research: game theory, network models, inventory models","Numerical computation: techniques for the computer implementation of algorithms for interpolation, approximation, numerical integration, etc","Graphical computation, modelling and simulation, high performance computation"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 461', 'Organization of Programming Languages', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Language definition structure, data types and structures. Review of basic data types, including lists and trees, control structures and data flow, run-time considerations, interpretative languages, lexical analysis and parsing. Functional programming languages; logic programming languages; object oriented programming languages.', '["Language definition structure, data types and structures","Review of basic data types, including lists and trees, control structures and data flow, run-time considerations, interpretative languages, lexical analysis and parsing","Functional programming languages","logic programming languages","object oriented programming languages"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 421', 'Database Design and Management', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Relational databases: mapping conceptual schema to relational schema; data models; normalisation; database connection in Linux/MySQL and Windows/Access; database access from a programming language. Practical exercises using a standard DBMS; analysis of Open Database Connectivity standard; stored procedures; object-oriented relational database management systems (e.g. Oracle). Data modelling, relational database design including entity relationship (ER) modelling with practical examples, report generation. DBMS terminology and concepts, transaction management, concurrency and recovery, physical design issues, database administrator functions, distributed databases.', '["Relational databases: mapping conceptual schema to relational schema","data models","normalisation","database connection in Linux/MySQL and Windows/Access","database access from a programming language","Practical exercises using a standard DBMS","analysis of Open Database Connectivity standard","stored procedures","object-oriented relational database management systems (e.g","Oracle)","Data modelling, relational database design including entity relationship (ER) modelling with practical examples, report generation","DBMS terminology and concepts, transaction management, concurrency and recovery, physical design issues, database administrator functions, distributed databases"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 431', 'Algorithms and Complexity Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Basic algorithmic analysis: asymptotic analysis of upper and average complexity bounds, standard complexity classes, time and space trade-off in algorithm analysis. Algorithm strategies: brute force, greedy, divide and conquer, recursive, backtracking, dynamic programming, heuristics, reduction (transform and conquer); implementation of data structures. Fundamental computing algorithms: numerical algorithms, sequential and binary search algorithms, sorting algorithms, binary search trees, hash tables, graphs and their representation.', '["Basic algorithmic analysis: asymptotic analysis of upper and average complexity bounds, standard complexity classes, time and space trade-off in algorithm analysis","Algorithm strategies: brute force, greedy, divide and conquer, recursive, backtracking, dynamic programming, heuristics, reduction (transform and conquer)","implementation of data structures","Fundamental computing algorithms: numerical algorithms, sequential and binary search algorithms, sorting algorithms, binary search trees, hash tables, graphs and their representation"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 433', 'Survey of Programming Languages', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Overview of programming languages; history of programming languages; brief survey of programming paradigms (procedural, object-oriented, functional, declarative-non-algorithmic, scripting languages); effects of scale on programming methodology. Language description, syntactic structure (expression notations, abstract syntax tree, lexical syntax, grammar for expression, variants of grammars). Language semantics (informal semantics; overview of formal semantics — denotational, axiomatic, operational). The concept of types, declaration models (binding, visibility, scope, lifetime), overview of type-checking, garbage collection. Abstraction mechanisms, parameterisation mechanisms (reference vs value), activation records and storage management, type parameters and parameterised types. Modules in programming languages; object oriented, functional and logic language paradigms.', '["Overview of programming languages","history of programming languages","brief survey of programming paradigms (procedural, object-oriented, functional, declarative-non-algorithmic, scripting languages)","effects of scale on programming methodology","Language description, syntactic structure (expression notations, abstract syntax tree, lexical syntax, grammar for expression, variants of grammars)","Language semantics (informal semantics","overview of formal semantics — denotational, axiomatic, operational)","The concept of types, declaration models (binding, visibility, scope, lifetime), overview of type-checking, garbage collection","Abstraction mechanisms, parameterisation mechanisms (reference vs value), activation records and storage management, type parameters and parameterised types","Modules in programming languages","object oriented, functional and logic language paradigms"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 441', 'Net-centric Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Distributed computing: system models for the distributed computing paradigm, architectural models — client/server model, peer-to-peer model, and variations. Mobile and wireless computing: introduction and overview, properties of wireless — PANs, WANs, network structure and architectures, including hand-off and mobility support at the physical/link level. Network security: foundational concepts — risk, threats, vulnerability, advanced requirements of security; human factors and security — ethics, regulatory environment, compliance and identity management, social engineering; principles of secure design — isolation, fail/safe, open, end-to-end security. Client/server computing (using the web), building web applications.', '["Distributed computing: system models for the distributed computing paradigm, architectural models — client/server model, peer-to-peer model, and variations","Mobile and wireless computing: introduction and overview, properties of wireless — PANs, WANs, network structure and architectures, including hand-off and mobility support at the physical/link level","Network security: foundational concepts — risk, threats, vulnerability, advanced requirements of security","human factors and security — ethics, regulatory environment, compliance and identity management, social engineering","principles of secure design — isolation, fail/safe, open, end-to-end security","Client/server computing (using the web), building web applications"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 463', 'Structured Programming', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Structured programming elements; models for representing structured programming elements, structured design principles — abstraction, modularity, stepwise refinement, structured design techniques. Program modularisation (bottom-up, top-down, nested virtual machine approaches); language features for structured programming; practical illustration using a RAD, e.g. Visual Basic. Graphical User Interface (GUI) concepts; event-driven programming; time manipulation; graphics; multimedia; device control. Students learn programming concepts using a project-centred approach.', '["Structured programming elements","models for representing structured programming elements, structured design principles — abstraction, modularity, stepwise refinement, structured design techniques","Program modularisation (bottom-up, top-down, nested virtual machine approaches)","language features for structured programming","practical illustration using a RAD, e.g","Visual Basic","Graphical User Interface (GUI) concepts","event-driven programming","time manipulation","graphics","multimedia","device control","Students learn programming concepts using a project-centred approach"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 412', 'Formal Methods and Software Development', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 2, 'Introduction to formal methods in software development: definition and meaning, motivations for use, myths about formal methods, commandments of formal methods. The Z notation: advantages and disadvantages, software formal specification and its rationale, software formal specification using Z.', '["Introduction to formal methods in software development: definition and meaning, motivations for use, myths about formal methods, commandments of formal methods","The Z notation: advantages and disadvantages, software formal specification and its rationale, software formal specification using Z"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 432', 'Human Computer Interface', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Foundation of HCI: definition and history of information architecture, types of information architecture, user-centred design, information architecture models and case studies, information architecture problem solving and development process. Visual design: introduction to visual design, design theory, information design, colour, visual perception theory. Principles of GUI, GUI toolkits, human-centred software evaluation and development, GUI design and programming.', '["Foundation of HCI: definition and history of information architecture, types of information architecture, user-centred design, information architecture models and case studies, information architecture problem solving and development process","Visual design: introduction to visual design, design theory, information design, colour, visual perception theory","Principles of GUI, GUI toolkits, human-centred software evaluation and development, GUI design and programming"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 438', 'Artificial Intelligence II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 2, 'Review of propositional and predicate logic; resolution and theorem proving; non-monotonic inference; probabilistic reasoning, Bayes'' theorem; natural language processing (information retrieval, language translation, speech recognition). Machine learning: definition and examples, supervised learning, decision tree learning, neural networks, the nearest neighbour algorithm, learning theory, the problem of overfitting, unsupervised learning, reinforcement learning. Introduction to robotics: overview, configuration, planning, sensing, programming, navigation and control. Expert systems; introduction to PROLOG, LISP or another AI programming language.', '["Review of propositional and predicate logic","resolution and theorem proving","non-monotonic inference","probabilistic reasoning, Bayes'' theorem","natural language processing (information retrieval, language translation, speech recognition)","Machine learning: definition and examples, supervised learning, decision tree learning, neural networks, the nearest neighbour algorithm, learning theory, the problem of overfitting, unsupervised learning, reinforcement learning","Introduction to robotics: overview, configuration, planning, sensing, programming, navigation and control","Expert systems","introduction to PROLOG, LISP or another AI programming language"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 490', 'Project', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 6, 'Must involve the development of a non-trivial system or application. A report on the work done by the student is submitted and defended before a panel of examiners consisting of members of the academic staff of the Department and possibly an external examiner.', '["Must involve the development of a non-trivial system or application","A report on the work done by the student is submitted and defended before a panel of examiners consisting of members of the academic staff of the Department and possibly an external examiner"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 339', 'Theory of Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Elective. Chomsky hierarchy: type 0, type 1, type 2 and type 3 grammars. Finite automata, deterministic and non-deterministic finite automata, conversion of non-deterministic to deterministic finite automata, regular expressions and their relationship to finite automata. Pushdown automata, context-free grammars: deterministic and non-deterministic pushdown automata; useless productions and the emptiness set; ambiguity; context-free grammars for pushdown automata and vice versa. Properties of context-free languages, pumping lemma, closure properties, existence of non-context-free languages. Turing machines, decidability and undecidability.', '["Chomsky hierarchy: type 0, type 1, type 2 and type 3 grammars","Finite automata, deterministic and non-deterministic finite automata, conversion of non-deterministic to deterministic finite automata, regular expressions and their relationship to finite automata","Pushdown automata, context-free grammars: deterministic and non-deterministic pushdown automata","useless productions and the emptiness set","ambiguity","context-free grammars for pushdown automata and vice versa","Properties of context-free languages, pumping lemma, closure properties, existence of non-context-free languages","Turing machines, decidability and undecidability"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 313', 'Operation Research', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Elective. Mathematical modelling; linear programming — formulating and solving linear programs, graphical method, simplex method, canonical form, two-phase simplex method, transportation problems and the transportation simplex method. Network problems: shortest path problem, minimum spanning tree, maximum flow problem, minimum-cost flow problem, network simplex algorithm. Project scheduling models (PSM and PERT); game theory — pure and mixed strategies, non-constant-sum games; inventory problems; reliability problems; dynamic programming; network scheduling models (PERT and CPM).', '["Mathematical modelling","linear programming — formulating and solving linear programs, graphical method, simplex method, canonical form, two-phase simplex method, transportation problems and the transportation simplex method","Network problems: shortest path problem, minimum spanning tree, maximum flow problem, minimum-cost flow problem, network simplex algorithm","Project scheduling models (PSM and PERT)","game theory — pure and mixed strategies, non-constant-sum games","inventory problems","reliability problems","dynamic programming","network scheduling models (PERT and CPM)"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 315', 'Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Elective. Using R as a calculator, basics of R syntax, R workspace, matrices and lists, subsetting. Data input and output, interface with other software packages. Writing your own code in R, R scripts. Exploratory data analysis — range, summary, mean, variance, median, standard deviation, histogram, box plot, scatter plot. Probability distribution simulation, conditional statements and loops in R. Statistical functions in R: statistical inference, contingency tables, chi-squared goodness of fit, regression, generalised linear models. Graphics beyond the basics, graphics and tables, working with large datasets, principles of exploratory data analysis (big data analysis), data frames in R.', '["Using R as a calculator, basics of R syntax, R workspace, matrices and lists, subsetting","Data input and output, interface with other software packages","Writing your own code in R, R scripts","Exploratory data analysis — range, summary, mean, variance, median, standard deviation, histogram, box plot, scatter plot","Probability distribution simulation, conditional statements and loops in R. Statistical functions in R: statistical inference, contingency tables, chi-squared goodness of fit, regression, generalised linear models","Graphics beyond the basics, graphics and tables, working with large datasets, principles of exploratory data analysis (big data analysis), data frames in R"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 317', 'Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 3, 'Elective. Techniques for interpolation; approximation — polynomial and spline approximation, orthogonal polynomial and Chebyshev approximations. Direct and numerical integration and differentiation; solution of non-linear equations; solution of ordinary differential equations; introduction to partial differential equations. Floating-point arithmetic; use of mathematical subroutine packages; error analysis and norms; computation of eigenvalues and eigenvectors; numerical solution of boundary-value problems for ordinary differential equations; solution of non-linear systems of algebraic equations; least-squares solution of over-determined systems.', '["Techniques for interpolation","approximation — polynomial and spline approximation, orthogonal polynomial and Chebyshev approximations","Direct and numerical integration and differentiation","solution of non-linear equations","solution of ordinary differential equations","introduction to partial differential equations","Floating-point arithmetic","use of mathematical subroutine packages","error analysis and norms","computation of eigenvalues and eigenvectors","numerical solution of boundary-value problems for ordinary differential equations","solution of non-linear systems of algebraic equations","least-squares solution of over-determined systems"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 343', 'Digital System Design', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, 'Elective. Boolean algebra: meaning, types/examples, theorems/laws, using truth tables to verify theorems and laws. Gates, gating devices, combinational logic, sequential logic. Methods of synthesis and minimisation of combinational circuits: SOP, POS, canonical forms, minterm and maxterm list forms, conversions between forms, using K-maps to minimise combinational circuits. Designs with multiplexers and demultiplexers, PLAs, memories — latches, flip-flops, shift registers, RAM and ROM, cache, and microprocessors.', '["Boolean algebra: meaning, types/examples, theorems/laws, using truth tables to verify theorems and laws","Gates, gating devices, combinational logic, sequential logic","Methods of synthesis and minimisation of combinational circuits: SOP, POS, canonical forms, minterm and maxterm list forms, conversions between forms, using K-maps to minimise combinational circuits","Designs with multiplexers and demultiplexers, PLAs, memories — latches, flip-flops, shift registers, RAM and ROM, cache, and microprocessors"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 435', 'Computer Graphics and Visualization', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Elective. Hardware aspects: plotters, microfilm plotters, display, graphic tablets, light pens, other graphical input aids, facsimile and its problems, refresh display, changing images, light pen interaction. Two- and three-dimensional transformation, perspective, clipping algorithms. Hidden line removal, bounded surface removal, Warnock''s method, shading, data reduction for graphical input. Introduction to handwriting and character recognition. Curve synthesis and fitting, contouring. Ring structures versus doubly linked lists, hierarchical structures, data structure organisation for interactive graphics.', '["Hardware aspects: plotters, microfilm plotters, display, graphic tablets, light pens, other graphical input aids, facsimile and its problems, refresh display, changing images, light pen interaction","Two- and three-dimensional transformation, perspective, clipping algorithms","Hidden line removal, bounded surface removal, Warnock''s method, shading, data reduction for graphical input","Introduction to handwriting and character recognition","Curve synthesis and fitting, contouring","Ring structures versus doubly linked lists, hierarchical structures, data structure organisation for interactive graphics"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 413', 'Computer System Performance Evaluation', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Elective. The programme table lists this as "COS 413"; the department''s own course description for this exact title is headed "COS 416" — the description is reused here under the table''s code. Computer system performance measures/parameters, applications, performance measurement techniques, simulation techniques, analytic techniques, work-load characterisation, performance evaluation in selected problems, performance evaluation in design problems, evaluation of program performance.', '["Computer system performance measures/parameters, applications, performance measurement techniques, simulation techniques, analytic techniques, work-load characterisation, performance evaluation in selected problems, performance evaluation in design problems, evaluation of program performance"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 415', 'Modeling & Simulation', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Elective. Basic definitions and uses, the simulation process, basic statistical distribution theory, models and simulation. Queues: basic components, Kendall notation, queuing rules, Little''s Law, queuing networks, special types of queues. Stochastic processes: discrete state and continuous state processes, Markov processes, birth-death processes, Poisson processes. Random numbers: types of random numbers, exercises.', '["Basic definitions and uses, the simulation process, basic statistical distribution theory, models and simulation","Queues: basic components, Kendall notation, queuing rules, Little''s Law, queuing networks, special types of queues","Stochastic processes: discrete state and continuous state processes, Markov processes, birth-death processes, Poisson processes","Random numbers: types of random numbers, exercises"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 437', 'Project Management', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Elective. Project and project life cycle; project management processes; structured project management; work breakdown structures (WBS) — developing WBS, using WBS to estimate effort and cost. Project scheduling: developing schedules, network diagrams, PERT and CPM, Gantt charts, using schedules to monitor and control projects. Resources and resource planning; cost planning and budgeting; change management; project risk management; ethical and commercial issues in project management.', '["Project and project life cycle","project management processes","structured project management","work breakdown structures (WBS) — developing WBS, using WBS to estimate effort and cost","Project scheduling: developing schedules, network diagrams, PERT and CPM, Gantt charts, using schedules to monitor and control projects","Resources and resource planning","cost planning and budgeting","change management","project risk management","ethical and commercial issues in project management"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 439', 'Game Programming', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Elective. Overview of Windows programming, overview of COM and DirectX, mathematics of rendering 3D objects, vectors and matrices, matrix multiplication, translation, rotation, scaling, view, projection. Direct3D: display modes, sprites and fonts, vertices and transformation matrices, textures, depth buffers, lighting. DirectX audio: DirectSound playback, DirectSound 3D effects, overview of DirectMusic. DirectInput: mouse, joystick and keyboard input. Introduction to OpenGL.', '["Overview of Windows programming, overview of COM and DirectX, mathematics of rendering 3D objects, vectors and matrices, matrix multiplication, translation, rotation, scaling, view, projection","Direct3D: display modes, sprites and fonts, vertices and transformation matrices, textures, depth buffers, lighting","DirectX audio: DirectSound playback, DirectSound 3D effects, overview of DirectMusic","DirectInput: mouse, joystick and keyboard input","Introduction to OpenGL"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 471', 'Web Application Development', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 2, 'Elective. Introduction to client-server architecture, common gateway interfaces. Common web development problems and solutions using server-side and client-side scripting techniques. Practical design and development of web pages using industry-standard scripting languages: XHTML, PHP, Perl. Creation of dynamic web pages. Web standards/technologies: Web 2.0, XML, SOAP, web services, etc.', '["Introduction to client-server architecture, common gateway interfaces","Common web development problems and solutions using server-side and client-side scripting techniques","Practical design and development of web pages using industry-standard scripting languages: XHTML, PHP, Perl","Creation of dynamic web pages","Web standards/technologies: Web 2.0, XML, SOAP, web services, etc"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 423', 'Formal Models of Computation', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Elective. Overview of the theory of computation, languages and strings, language hierarchy, the task of language recognition, the power of encoding. A machine-based hierarchy of language classes; a tractability hierarchy of language classes. Computation, decision procedures, determinism and nondeterminism, functions on languages and programs. Finite state machines and regular languages: deterministic FSMs, regular languages, designing deterministic FSMs, nondeterministic FSMs, simulators for FSMs, minimising FSMs, a canonical form for regular languages. Regular expressions, applications, manipulation and simplification of regular expressions. Regular grammars and regular languages; regular and nonregular languages; algorithms and decision procedures for regular languages. Context-free languages and pushdown automata: rewrite systems and grammars, context-free grammars (CFG) and languages, designing and simplifying CFGs, proving a grammar is correct, derivations and parse trees, ambiguity. Pushdown automata: definition of a nondeterministic PDA, deterministic and nondeterministic PDAs, equivalence of CFG and PDAs, nondeterminism and halting. Context-free and noncontext-free languages, algorithms and decision procedures for context-free languages, context-free parsing — lexical analysis, top-down parsing, bottom-up parsing, parsing natural languages. Turing machines and undecidability: definition, notation and examples, computing with Turing machines, adding multiple tapes and nondeterminism, simulating a "real" computer, alternative Turing machines, the Church-Turing thesis, the unsolvability of the halting problem, decidability and undecidability.', '["Overview of the theory of computation, languages and strings, language hierarchy, the task of language recognition, the power of encoding","A machine-based hierarchy of language classes","a tractability hierarchy of language classes","Computation, decision procedures, determinism and nondeterminism, functions on languages and programs","Finite state machines and regular languages: deterministic FSMs, regular languages, designing deterministic FSMs, nondeterministic FSMs, simulators for FSMs, minimising FSMs, a canonical form for regular languages","Regular expressions, applications, manipulation and simplification of regular expressions","Regular grammars and regular languages","regular and nonregular languages","algorithms and decision procedures for regular languages","Context-free languages and pushdown automata: rewrite systems and grammars, context-free grammars (CFG) and languages, designing and simplifying CFGs, proving a grammar is correct, derivations and parse trees, ambiguity","Pushdown automata: definition of a nondeterministic PDA, deterministic and nondeterministic PDAs, equivalence of CFG and PDAs, nondeterminism and halting","Context-free and noncontext-free languages, algorithms and decision procedures for context-free languages, context-free parsing — lexical analysis, top-down parsing, bottom-up parsing, parsing natural languages","Turing machines and undecidability: definition, notation and examples, computing with Turing machines, adding multiple tapes and nondeterminism, simulating a \"real\" computer, alternative Turing machines, the Church-Turing thesis, the unsolvability of the halting problem, decidability and undecidability"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 451', 'Laboratory for Digital System Design', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'first', 3, 'Elective. General instrumentation; use of meters in DC and AC measurements; rectifiers, electrodynamometer and wattmeter, instrument transformers, oscilloscopes, square wave, pulse, signal and function generators, wave analyser; logic probes/analysers; troubleshooting; analysing electronic circuits; implementation of digital logic circuits.', '["General instrumentation","use of meters in DC and AC measurements","rectifiers, electrodynamometer and wattmeter, instrument transformers, oscilloscopes, square wave, pulse, signal and function generators, wave analyser","logic probes/analysers","troubleshooting","analysing electronic circuits","implementation of digital logic circuits"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 472', 'Distributed Computing System', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 2, 'Elective. Characterisation of distributed systems: definitions and meaning, examples of distributed systems, trends in distributed systems, resource sharing in distributed systems, challenges of distributed systems. Distributed system models: physical models, architectural models, fundamental models. Networking and internetworking: types of network, network principles, internet protocols. Interprocess communication.', '["Characterisation of distributed systems: definitions and meaning, examples of distributed systems, trends in distributed systems, resource sharing in distributed systems, challenges of distributed systems","Distributed system models: physical models, architectural models, fundamental models","Networking and internetworking: types of network, network principles, internet protocols","Interprocess communication"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 404', 'Special Topics in Computer Science', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Elective. Special topics from any area of computer science considered relevant at any given time. Topics are expected to change from year to year. Apart from seminars given by lecturers and guests, students are expected to do substantial reading on their own.', '["Special topics from any area of computer science considered relevant at any given time","Topics are expected to change from year to year","Apart from seminars given by lecturers and guests, students are expected to do substantial reading on their own"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 478', 'Information Technology Law', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Elective. Information Technology Act; rules under the Information Technology Act; the rule of cyberspace; regulating the information superhighway; cyber law policy issues and emerging trends; anonymous blog regulation versus free speech; jurisdiction and the internet; online contracts; digital signatures — legal implications; cyber crime; data protection; liability of intermediaries; copyright and the internet; internet and free speech; domain name disputes and notable cases (Yahoo v LICRA; Zippo Manufacturing v Zippo.com; ProCD v Zeidenberg; US v Morris; US v Thomas; Viacom v Google).', '["Information Technology Act","rules under the Information Technology Act","the rule of cyberspace","regulating the information superhighway","cyber law policy issues and emerging trends","anonymous blog regulation versus free speech","jurisdiction and the internet","online contracts","digital signatures — legal implications","cyber crime","data protection","liability of intermediaries","copyright and the internet","internet and free speech","domain name disputes and notable cases (Yahoo v LICRA","Zippo Manufacturing v Zippo.com","ProCD v Zeidenberg","US v Morris","US v Thomas","Viacom v Google)"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 414', 'Queuing System Performance Evaluation', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 2, 'Elective. Introduction to queuing systems: definition, components, performance metrics, examples of queuing systems. Types of queuing systems: pure birth and pure death queuing systems, single server versus parallel server queuing systems, finite versus infinite queuing systems, single queuing system versus queuing network. Kendall notation; birth-death queuing models — generalised and specified models, steady state probabilities, Little''s law; Markovian queues up to M/G/1; simple queues in computer networks; bounds, inequalities and approximations.', '["Introduction to queuing systems: definition, components, performance metrics, examples of queuing systems","Types of queuing systems: pure birth and pure death queuing systems, single server versus parallel server queuing systems, finite versus infinite queuing systems, single queuing system versus queuing network","Kendall notation","birth-death queuing models — generalised and specified models, steady state probabilities, Little''s law","Markovian queues up to M/G/1","simple queues in computer networks","bounds, inequalities and approximations"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 436', 'Special Topics in Software Engineering', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Elective. Special topics from any area of Software Engineering considered relevant at any given time. Topics are expected to change from year to year. Apart from seminars given by lecturers and guests, students are expected to do substantial reading on their own.', '["Special topics from any area of Software Engineering considered relevant at any given time","Topics are expected to change from year to year","Apart from seminars given by lecturers and guests, students are expected to do substantial reading on their own"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 434', 'Compiler Construction II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Elective. Programming language syntax, semantics and pragmatics; overview of translators — compilers, assemblers and interpreters; phases of compilation; structure of a compiler; lexical analysis, syntax analysis, expression analysis, code generation, code optimisation, error detection and recovery. Grammar and language; construction of scanner and parser; internal representation of a program; recognisers, top-down and bottom-up; run-time storage organisation, LR grammar and analysers; construction of LR grammar, analyser and LR table; organisation of symbol tables; translator writing systems.', '["Programming language syntax, semantics and pragmatics","overview of translators — compilers, assemblers and interpreters","phases of compilation","structure of a compiler","lexical analysis, syntax analysis, expression analysis, code generation, code optimisation, error detection and recovery","Grammar and language","construction of scanner and parser","internal representation of a program","recognisers, top-down and bottom-up","run-time storage organisation, LR grammar and analysers","construction of LR grammar, analyser and LR table","organisation of symbol tables","translator writing systems"]'::jsonb, 'Department of Computer Science course outline'),
  ('COS 452', 'Advanced Digital Laboratory', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '400 Level', 'second', 3, 'Elective. Understanding and troubleshooting computer hardware circuits: motherboard, multi-core processors, monitor, printer, drive, card, power supplies, etc. Modems; PC assembling and disassembling; hardware and software installations; input/output ports, hard disk drives, floppy disk drives, motherboards, memories and troubleshooting of digital circuits using standard equipment; implementation of specific projects in the microprocessor laboratory.', '["Understanding and troubleshooting computer hardware circuits: motherboard, multi-core processors, monitor, printer, drive, card, power supplies, etc","Modems","PC assembling and disassembling","hardware and software installations","input/output ports, hard disk drives, floppy disk drives, motherboards, memories and troubleshooting of digital circuits using standard equipment","implementation of specific projects in the microprocessor laboratory"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 111', 'Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Elementary Set theory, subsets, union, intersection, complements. Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity.', '["Elementary Set theory, subsets, union, intersection, complements", "Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 121', 'Elementary Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Functions of a real variable, graphs, limits and continuity. The derivative as limit of rate of change. Techniques of differentiation. Curve sketching, integration as an inverse of differentiation. Methods of integration, definite integrals. Application of integration to areas and volumes.', '["Functions of a real variable, graphs, limits and continuity", "The derivative as limit of rate of change", "Techniques of differentiation", "Curve sketching, integration as an inverse of differentiation", "Methods of integration, definite integrals", "Application of integration to areas and volumes"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 115', 'General Physics for Physical Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Units and dimensions. Elements of vector algebra. Kinematics, linear and circular motion. Laws of mechanics and gravitation, simple applications, motion of planets. Conservation laws, energy, momentum; work and power. Rigid bodies, moment of inertia. Angular momentum. Simple harmonic motion, simple and compound pendulums, damped and forced vibrations. Elasticity, moduli of elasticity, bending moments, fluid mechanics.', '["Units and dimensions", "Elements of vector algebra", "Kinematics, linear and circular motion", "Laws of mechanics and gravitation, simple applications, motion of planets", "Conservation laws, energy, momentum", "Work and power", "Rigid bodies, moment of inertia", "Angular momentum", "Simple harmonic motion, simple and compound pendulums, damped and forced vibrations", "Elasticity, moduli of elasticity, bending moments, fluid mechanics"]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 101', 'Study Skills and Basic Research Methods', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 2, 'Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, The English Language and the Nigerian society, World English, Levels and Varieties of English — formal, informal, standard, etc., English in Literature and the Media.

Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes, English Language Register, diatypes and dialects.

Listening skill - The listening skill discussed as a receptive and reciprocal activity, Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening.

Reading Skill - The concept of reading as a linguistic organization and a vehicle of communication. Reading Problems, Levels of Reading, Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies (Scanning, Skimming, Phrase reading, Intensive & Extensive reading, Exploiting the topic sentence for main ideas), Reading for details, Reading for evaluation and inference, Reading with questions - SQ3R, PR3, Methods for understanding difficult words in a reading text, Literature reading for study, analysis and comment.

Speaking & Communication Skills - Nature, Process & Development, Principles of Public Speech Making and Social Interaction, The Speech Sounds of English and their Articulation, Phonetic Transcription and Practical Speech Work.

Study Techniques - Choosing study centers and discussion groups, Note-taking during lectures, and from audio-visual equipment, Note-making techniques during private reading and literature search, Summary & Transcoding Techniques, Retrieving information from notes, The dictionary as a study guide.

Basic Research Methods & Term Paper Writing - Research – meaning & nature, Types & Methodology; Data in the Research Process, The Research Report, Process and Techniques, Documentation in Research Reports: Process, Types and Methods, Abbreviations in Research Reports, The term paper as a miniature research report, Practical term paper writing.

Course Evaluation & Grading - Students must attend at least 75% of the lectures to qualify for examination in the course.', '["Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, World English, Levels and Varieties of English", "Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes", "Listening skill - Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening", "Reading Skill - Reading Problems, Levels and Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies, Reading for evaluation and inference", "Speaking & Communication Skills - Principles of Public Speech Making and Social Interaction, Phonetic Transcription and Practical Speech Work", "Study Techniques - Note-taking, Note-making, Summary & Transcoding Techniques", "Basic Research Methods & Term Paper Writing - The Research Report, Documentation, Abbreviations, practical term paper writing"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 111', 'The Use of library and Study Skills', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 2, 'Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users. Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes. Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information in the library. Reference sources: types of reference sources and services. Web resources and online resources. Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism. Learning skills and research skills, ICT skillsets: types of learning and information policies.', '["Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users", "Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes", "Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information", "Reference sources: types of reference sources and services. Web resources and online resources", "Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism", "Learning skills and research skills, ICT skillsets: types of learning and information policies"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('PHY 191', 'Practical Physics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Elective. Selected experiments from the 100-Level courses in Physics for service courses.', '["Selected experiments from the 100-Level courses in Physics for service courses"]'::jsonb, 'Department of Computer Science course outline'),
  ('CHM 101', 'Basic Principles of Inorganic Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 2, 'Elective. Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear Chemistry: Radioactivity and its practical applications.', '["Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories", "Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position", "Nuclear Chemistry: Radioactivity and its practical applications"]'::jsonb, 'Department of Computer Science course outline'),
  ('BIO 151', 'General Biology I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 3, 'Elective.', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('STA 131', 'Inference I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'first', 2, 'Elective. Statistical Data: sources, collection, presentation and analysis. Measures of central tendency and dispersion, skewness. Moments and kurtosis. Index numbers and demographic measures.', '["Statistical Data: sources, collection, presentation and analysis", "Measures of central tendency and dispersion, skewness", "Moments and kurtosis", "Index numbers and demographic measures"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 122', 'Elementary Mathematics III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 3, 'Geometric representation of vectors in 1-3 dimensions, Components, direction cosines. Addition of vectors and multiplication of vectors by a scalar, linear independence. Scalar and vector products of two vectors. Differentiation and integration of vectors with respect to a scalar variable. Two-dimensional coordinate geometry. Straight lines, circles, parabolas, ellipses, hyperbolas. Tangents and normals. Kinematics of a particle. Components of velocity and acceleration of a particle moving in a plane. Force and momentum. Newton''s laws of motion; motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum. Impact of two smooth elastic spheres. Direct and oblique impacts.', '["Geometric representation of vectors in 1-3 dimensions, Components, direction cosines", "Addition of vectors and multiplication of vectors by a scalar, linear independence", "Scalar and vector products of two vectors", "Differentiation and integration of vectors with respect to a scalar variable", "Two-dimensional coordinate geometry", "Straight lines, circles, parabolas, ellipses, hyperbolas", "Tangents and normals", "Kinematics of a particle", "Components of velocity and acceleration of a particle moving in a plane", "Force and momentum", "Newton''s laws of motion", "Motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum", "Impact of two smooth elastic spheres", "Direct and oblique impacts"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 116', 'General Physics for Physical Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 2, 'Temperature and its measurement. Heat capacity, specific heat, latent heats, critical points. Calorimetry. Gas laws; kinetic theory of gases; thermal energy, work done by expanding gases; laws of thermodynamics. Liquefaction of gases. Heat transfer: conduction, convection, radiation. Longitudinal and transverse waves; vibrations in solids. Sound waves in solids, liquids, gases; pitch, intensity and quality of sound. Doppler Effect. Acoustics of buildings. Ultrasonics. Reflection and refraction of light; spherical mirrors; thin and thick lenses; optical instruments. Wave nature of light; interference, diffraction, polarization. Velocity of light.', '["Temperature and its measurement", "Heat capacity, specific heat, latent heats, critical points", "Calorimetry", "Gas laws", "Kinetic theory of gases", "Thermal energy, work done by expanding gases", "Laws of thermodynamics", "Liquefaction of gases", "Heat transfer: conduction, convection, radiation", "Longitudinal and transverse waves", "Vibrations in solids", "Sound waves in solids, liquids, gases", "Pitch, intensity and quality of sound", "Doppler Effect", "Acoustics of buildings", "Ultrasonics", "Reflection and refraction of light", "Spherical mirrors", "Thin and thick lenses", "Optical instruments", "Wave nature of light", "Interference, diffraction, polarization", "Velocity of light"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 118', 'General Physics for Physical Sciences III', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 2, 'Electrostatics; Coulomb''s law, electric field, Gauss''s law, electrostatic potential, fields due to simple charge distributions. Energy in electric fields, capacitance. Dielectrics, polarization. Electric current, Ohm''s law. Elements of circuit theory. Thermoelectric effect. Magnetic effects of current. Ampere''s law, fields due to simple circuits. Permanent magnetism, Earth''s magnetic field; ferromagnetism, moving coil instruments. Faraday''s law of induction; generators, electric motors. Alternating current. Maxwell''s equations. Elements of atomic and nuclear physics.', '["Electrostatics", "Coulomb''s law, electric field, Gauss''s law, electrostatic potential, fields due to simple charge distributions", "Energy in electric fields, capacitance", "Dielectrics, polarization", "Electric current, Ohm''s law", "Elements of circuit theory", "Thermoelectric effect", "Magnetic effects of current", "Ampere''s law, fields due to simple circuits", "Permanent magnetism, Earth''s magnetic field", "Ferromagnetism, moving coil instruments", "Faraday''s law of induction", "Generators, electric motors", "Alternating current", "Maxwell''s equations", "Elements of atomic and nuclear physics"]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 102', 'Basic Grammar and Varieties of Writing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 2, 'Part A: Basic Grammar: Introduction. The concept of grammar and its place in language teaching and learning. Parts of speech and their functions (treated in detail). Closed and open class items in parts of speech, Nominalization, Grammatical Structures: the phrase, the clause and the sentence. Elementary Clause Analysis, Sentence Types, Elements and Patterns. Agreement (Grammatical agreement, Notional agreement, Proximity agreement) Agreement with the correlatives. Direct and Reported Speech, Error typology identification and correction.

Part B: Varieties of writing. Introduction (The Meaning, Nature and Purpose of Writing, Writing Types or Genres and their Characteristics). The paragraph as the basic unit of an essay (Types, Development of the Paragraph, Methods of Paragraph Development, The thesis statement). Point of view and style in writing. Qualities of a good piece of writing: Form, Diction and Content in writing. The Mechanics of Writing: punctuation, spelling and capitalization.

Part C: Writing Genres - Planning and choosing your theme. Deciding your genre. Choosing and developing your plot. Point of view, setting and characterization. Using the language that works. Essay Writing — Narration, Description, Exposition and Argumentation. Technical Writing: Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes, own story for practice, Computer-linked writing, types, style, language, and process.', '["Part A: Basic Grammar - The concept of grammar, Parts of speech, Grammatical Structures, Sentence Types, Agreement, Direct and Reported Speech, Error typology", "Part B: Varieties of writing - Meaning, Nature and Purpose of Writing, the paragraph as the basic unit of an essay, the thesis statement, Qualities of a good piece of writing, Mechanics of Writing", "Part C: Writing Genres - Planning and choosing your theme, plot, point of view, setting and characterization", "Essay Writing - Narration, Description, Exposition and Argumentation", "Technical Writing - Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('MTH 132', 'Elementary Mechanics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 3, 'Elective. Vectors: Algebra of vectors; coplanar forces; their resolution into components, equilibrium conditions, moments and couples, parallel forces; friction; centroids and centres of gravity of particles and rigid bodies; equivalence of sets of coplanar forces. Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion. Dynamics of a particle. Newton''s laws of motion; motion of connected particles.', '["Vectors: Algebra of vectors", "Coplanar forces", "Their resolution into components, equilibrium conditions, moments and couples, parallel forces", "Friction", "Centroids and centres of gravity of particles and rigid bodies", "Equivalence of sets of coplanar forces", "Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion", "Dynamics of a particle", "Newton''s laws of motion", "Motion of connected particles"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 122', 'Fundamentals of Physics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 3, 'Elective. Heat and temperature. Calorimetry. Laws of thermodynamics. Change of state - Critical points. Heat transfer; conduction, convection and radiation. Blackbody radiation. Wave motions, longitudinal and transverse waves. Superposition of waves, interference and diffraction. Propagation of waves in material media, vibrations in solids; sound wave. Wave theory of light, polarization of light. Rectilinear propagation of light, reflection, refraction; mirrors and lenses, lens combinations, optical instruments. Doppler Effect.', '["Heat and temperature", "Calorimetry", "Laws of thermodynamics", "Change of state - Critical points", "Heat transfer", "Conduction, convection and radiation", "Blackbody radiation", "Wave motions, longitudinal and transverse waves", "Superposition of waves, interference and diffraction", "Propagation of waves in material media, vibrations in solids", "Sound wave", "Wave theory of light, polarization of light", "Rectilinear propagation of light, reflection, refraction", "Mirrors and lenses, lens combinations, optical instruments", "Doppler Effect"]'::jsonb, 'Department of Computer Science course outline'),
  ('STA 132', 'Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 2, 'Elective. Elementary Time Series Analysis. Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion. Tests of significance for means and proportions. Simple linear regression and correlation.', '["Elementary Time Series Analysis", "Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion", "Tests of significance for means and proportions", "Simple linear regression and correlation"]'::jsonb, 'Department of Computer Science course outline'),
  ('STA 172', 'Statistical Computing', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '100 Level', 'second', 2, 'Elective. Generation of data using table of random numbers. Presentation and analysis of data. Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation. Test of significance, one sample only.', '["Generation of data using table of random numbers", "Presentation and analysis of data", "Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation", "Test of significance, one sample only"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 351', 'Electronics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Electronic device characteristics, equivalent circuit; various types of amplifiers, frequency and phase response, distortion, feedback oscillators. Semi-conductor theory and devices, characteristics; Lasers and Masers; four terminal network; equivalent circuits. Communication systems; modulation, a.m., f.m., single side band; demodulation. Elements of logic circuitry. Analog to digital conversion. Computers.

Prerequisite: PHY 251', '["Electronic device characteristics, equivalent circuit", "Various types of amplifiers, frequency and phase response, distortion, feedback oscillators", "Semi-conductor theory and devices, characteristics", "Lasers and Masers", "Four terminal network", "Equivalent circuits", "Communication systems", "Modulation, a.m., f.m., single side band", "Demodulation", "Elements of logic circuitry", "Analog to digital conversion", "Computers"]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 201', 'The Social Sciences', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, '', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 207', 'Logic, Philosophy and Human Existence', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, '', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 215', 'Linear Algebra I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Elective. System of linear equations. Matrices and algebra of matrices. Vector spaces over the real field. Subspaces, linear independence, bases and dimensions. Gram-Schmidt orthogonalization procedure. Linear transformations: range, null space and rank. Singular and non-singular transformations.', '["System of linear equations", "Matrices and algebra of matrices", "Vector spaces over the real field", "Subspaces, linear independence, bases and dimensions", "Gram-Schmidt orthogonalization procedure", "Linear transformations: range, null space and rank", "Singular and non-singular transformations"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 211', 'Sets, Logic and Algebra', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 3, 'Elective. Introduction to the language and concepts of modern mathematics; topics include: Basic set theory, mappings, relations, equivalence and other relations, Cartesian product. Binary logic, methods of proof. Binary operations, algebraic structures, semi-groups, rings, integral domains, fields, Homomorphism. Number systems; properties of integers, rationals, real and complex numbers.', '["Introduction to the language and concepts of modern mathematics", "Topics include: Basic set theory, mappings, relations, equivalence and other relations, Cartesian product", "Binary logic, methods of proof", "Binary operations, algebraic structures, semi-groups, rings, integral domains, fields, Homomorphism", "Number systems", "Properties of integers, rationals, real and complex numbers"]'::jsonb, 'Department of Computer Science course outline'),
  ('STA 205', 'Statistics for Physical Sciences and Engineering I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'first', 2, 'Elective. Frequency Distributions. Elements of Probability. Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric. Continuous probability distributions: Normal, Student''s $t$, Chi-square $\chi^2$ and $F$. Combinatorial and moment generating functions.', '["Frequency Distributions", "Elements of Probability", "Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric", "Continuous probability distributions: Normal, Student''s $t$, Chi-square $\\chi^2$ and $F$", "Combinatorial and moment generating functions"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 242', 'Mathematical Methods', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Real-valued functions of a real variable. Review of differentiation and integration and their applications. Mean-value theorem. Taylor series. Real-valued functions of two or three variables. Partial derivatives. Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations. Evaluation of line-integrals. Multiple integrals.', '["Real-valued functions of a real variable", "Review of differentiation and integration and their applications", "Mean-value theorem", "Taylor series", "Real-valued functions of two or three variables", "Partial derivatives", "Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations", "Evaluation of line-integrals", "Multiple integrals"]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 202', 'Issues in Peace and Conflict Studies', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, '', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('GSP 208', 'Nigerian Peoples and Cultures', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, '', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 216', 'Linear Algebra II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Elective. Representations of linear transformations by matrices, change of bases, equivalence and similarity. Determinants. Eigenvalues and eigenvectors. Minimum and characteristic polynomials of a linear transformation. Cayley-Hamilton theorem, bilinear and quadratic forms, orthogonal diagonalization. Canonical forms.', '["Representations of linear transformations by matrices, change of bases, equivalence and similarity", "Determinants", "Eigenvalues and eigenvectors", "Minimum and characteristic polynomials of a linear transformation", "Cayley-Hamilton theorem, bilinear and quadratic forms, orthogonal diagonalization", "Canonical forms"]'::jsonb, 'Department of Computer Science course outline'),
  ('MTH 222', 'Elementary Differential Equations I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 3, 'Elective. First-order ordinary differential equations. Existence and uniqueness of solution. Second-order ordinary differential equations with constant coefficients. General theory of $n$th-order linear ordinary differential equations. The Laplace transform. Solution of initial- and boundary-value problems by Laplace transform method. Simple treatment of partial differential equations in two independent variables. Applications of ordinary and partial differential equations to physical, life and engineering problems.', '["First-order ordinary differential equations", "Existence and uniqueness of solution", "Second-order ordinary differential equations with constant coefficients", "General theory of $n$th-order linear ordinary differential equations", "The Laplace transform", "Solution of initial- and boundary-value problems by Laplace transform method", "Simple treatment of partial differential equations in two independent variables", "Applications of ordinary and partial differential equations to physical, life and engineering problems"]'::jsonb, 'Department of Computer Science course outline'),
  ('PHY 242', 'Waves', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 3, 'Elective. General properties of wave motion, longitudinal and transverse waves, polarization of transverse waves, progressive and standing waves, interference of waves. Propagation of waves: effect of medium, dispersion, phase and group velocity, attenuation of waves. Wave equations, various solutions; reflection and refraction of waves. Vibrating strings, longitudinal waves in metal bar; free and forced vibrations, resonance. Coupled systems. Fourier analysis. Elastic waves in solids. Interference and diffraction of light, interferometers, diffraction gratings, polarization of light - production and analysis of polarized light.

Prerequisite: PHY 116 or PHY 122', '["General properties of wave motion, longitudinal and transverse waves, polarization of transverse waves, progressive and standing waves, interference of waves", "Propagation of waves: effect of medium, dispersion, phase and group velocity, attenuation of waves", "Wave equations, various solutions", "Reflection and refraction of waves", "Vibrating strings, longitudinal waves in metal bar", "Free and forced vibrations, resonance", "Coupled systems", "Fourier analysis", "Elastic waves in solids", "Interference and diffraction of light, interferometers, diffraction gratings, polarization of light - production and analysis of polarized light"]'::jsonb, 'Department of Computer Science course outline'),
  ('STA 206', 'Statistics for Physical Sciences and Engineering II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '200 Level', 'second', 2, 'Elective. Estimation: point and interval. Test of significance. Regression and correlation. Analysis of variance: one-way and two-way with no interaction.', '["Estimation: point and interval", "Test of significance", "Regression and correlation", "Analysis of variance: one-way and two-way with no interaction"]'::jsonb, 'Department of Computer Science course outline'),
  ('CED 341', 'Introduction to Entrepreneurship', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Computer Science', '300 Level', 'first', 2, '', '[]'::jsonb, 'Department of Computer Science course outline'),
